const toast=document.getElementById('toast'),content=document.getElementById('pageContent'),crumb=document.getElementById('crumbTitle'),drawer=document.getElementById('detailDrawer'),backdrop=document.getElementById('drawerBackdrop');
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function parseField(f){let [label,type='text']=f;if(type.startsWith('select:'))return{label,type:'select',options:type.slice(7).split(',')};if(type.startsWith('radio:'))return{label,type:'radio',options:type.slice(6).split(',')};return{label,type}}
function fieldHTML(f){let x=Array.isArray(f)?parseField(f):f;let placeholder=x.placeholder||('Isi '+x.label.toLowerCase());if(x.type==='select')return `<label class="field"><span>${esc(x.label)}</span><select><option value="">${esc(x.options[0]?.startsWith('Pilih')?x.options[0]:'Semua / pilih')}</option>${x.options.filter(o=>!o.startsWith('Pilih')).map(o=>`<option>${esc(o)}</option>`).join('')}</select></label>`;if(x.type==='radio')return `<fieldset class="field radio-field"><legend>${esc(x.label)}</legend><div>${x.options.map(o=>`<label><input type="radio" name="${esc(x.label)}"> ${esc(o)}</label>`).join('')}</div></fieldset>`;if(x.type==='file')return `<label class="field"><span>${esc(x.label)}</span><input type="file" disabled aria-label="${esc(x.label)}"></label>`;return `<label class="field"><span>${esc(x.label)}</span><input type="${esc(x.type)}" placeholder="${esc(placeholder)}" ${x.type==='readonly'?'readonly':''} ${x.type==='readonly'?'value="Dibuat sistem"':''}></label>`}
function status(text='Belum diperiksa'){return `<span class="status muted">${esc(text)}</span>`}
function pageHeader(p){let a=(p.actions||[]).find(x=>/Tambah|Buat|Daftarkan|Jadwalkan/.test(x));let addUser=window.currentPage==='users'&&a==='Tambah Pengguna Baru';let back=['userAdd','userPassword'].includes(window.currentPage)?'<button class="button" data-page="users">← Kembali ke Manajemen User</button>':'';return `<div class="page-title-row"><div><span class="eyebrow">${esc(p.module||'Alfar ERP')}</span><h1 class="page-title">${esc(p.title)}</h1><p class="page-subtitle">${esc(p.desc||'')}</p></div><div class="title-actions">${back}${a?`<button class="button primary" ${addUser?'data-page="userAdd"':`data-action="${esc(a)}"`}>＋ ${esc(a)}</button>`:''}</div></div>`}
function kpiCard([label,value,desc]){return `<div class="stat-card"><div class="stat-top"><span class="stat-label">${esc(label)}</span><span class="stat-icon">◈</span></div><div class="stat-value">${esc(value)}</div><div class="stat-foot">${esc(desc)}</div></div>`}
function tableHTML(p){if(!p.columns)return '';let rows=p.rows||[];return `<section class="card table-card"><div class="card-header"><div><h2 class="card-title">${p.tableTitle||'Daftar data'}</h2><p class="card-desc">Kolom dipertahankan dari halaman aktual atau diberi label ilustrasi bila belum teramati.</p></div>${p.filters?.some(f=>['search','search:','Cari'].some(x=>String(f[1]).startsWith('search')))?'<input class="search table-search" placeholder="Cari di tabel…">':''}</div><div class="table-wrap"><table class="data-table"><thead><tr>${p.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${p.columns.map((c,i)=>`<td>${i===0?`<span class="cell-main">${esc(row[i]||'—')}</span>`:i===p.columns.length-1&&/Aksi/i.test(c)?String(row[i]||'Detail').split(/[·,]/).map(a=>a.trim()).filter(Boolean).map(a=>`<button class="row-action" data-row-action="${esc(a)}">${esc(a)}</button>`).join(' '):esc(row[i]||'—')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${p.columns.length}"><div class="empty-state"><span class="empty-icon">▤</span><strong>Belum ada data untuk contoh layar ini</strong><p>Data bisnis tidak disalin ke prototype.</p></div></td></tr>`}</tbody></table></div><div class="table-footer"><span>Contoh tampilan · data aktual tidak dimuat</span><div class="pagination"><button>‹</button><button class="current">1</button><button>2</button><button>›</button></div></div></section>`}
function renderDashboard(p){return `${pageHeader(p)}<div class="illustration-note">ⓘ Prototipe visual · data aktual tidak ditampilkan</div><div class="stats-grid">${p.kpis.map(kpiCard).join('')}</div><div class="dashboard-grid"><section class="card"><div class="card-header"><div><h2 class="card-title">Monitoring proses operasional</h2><p class="card-desc">Urutan lintas modul dengan jalur Fresh dan Frozen tetap terpisah.</p></div><span class="status info">Ringkasan</span></div><div class="flow-track"><button class="flow-node done" data-page="poActive"><span class="flow-step">01 · Order</span><strong>PO / Reguler / MBG</strong><small>Permintaan & customer</small></button><button class="flow-node done" data-page="scheduleTarget"><span class="flow-step">02 · PPIC</span><strong>Schedule target</strong><small>Target & bahan baku</small></button><button class="flow-node active" data-page="freshReceipt"><span class="flow-step">03 · Bahan baku</span><strong>Tally Fresh / Frozen</strong><small>Penerimaan & distribusi</small></button><button class="flow-node" data-page="dailyProduction"><span class="flow-step">04 · Produksi</span><strong>SPK & tahapan</strong><small>Gramasi · chilling · pack</small></button><button class="flow-node" data-page="loadingShipping"><span class="flow-step">05 · Fulfillment</span><strong>Finish Good & shipping</strong><small>Loading · surat jalan</small></button></div><div class="flow-note"><span>✦</span><span><b>Alur yang dipertahankan:</b> PO → schedule target → kebutuhan material → tally fresh/frozen → distribusi → SPK → hasil proses / reject / retur → Finish Good → loading & shipping.</span></div></section><section class="card"><div class="card-header"><div><h2 class="card-title">Pintu akses cepat</h2><p class="card-desc">Akses modul yang sering dipakai.</p></div></div><div class="shortcut-list"><button data-page="users">Manajemen User <span>›</span></button><button data-page="poInput">Input PO <span>›</span></button><button data-page="frozenReceipt">Tally Frozen Masuk <span>›</span></button><button data-page="freshReceipt">Tally Fresh Masuk <span>›</span></button><button data-page="materialDistribution">Distribusi Material <span>›</span></button><button data-page="spk">SPK <span>›</span></button></div></section></div><div class="lower-grid"><section class="card"><div class="card-header"><div><h2 class="card-title">Progres produksi per tahap</h2><p class="card-desc">Metrik dari dashboard aktual: target, gramasi-chilling, gramasi-FG, pack, Finish Good, dan BB.</p></div><button class="text-link" data-page="productionDisplay">Buka monitoring →</button></div><div class="stage-grid"><div><span>Target Produksi</span><b>—</b><i>Pack</i></div><div><span>Gramasi-Chilling</span><b>—</b><i>Kg</i></div><div><span>Gramasi-FinishGood</span><b>—</b><i>Kg</i></div><div><span>Hasil Pack</span><b>—</b><i>Kg / pack</i></div><div><span>Finish Good</span><b>—</b><i>Kg / pack</i></div><div><span>BB Fresh / Frozen</span><b>— / —</b><i>Kg</i></div></div></section><section class="card"><div class="card-header"><div><h2 class="card-title">Perlu ditinjau</h2><p class="card-desc">Peringatan berdasarkan status, bukan angka hardcode.</p></div></div><div class="attention-list"><div class="attention-item"><i class="attention-marker"></i><div><strong>PO dengan kebutuhan BB</strong><small>Buka analisa PO dan schedule target</small></div><button class="row-action" data-page="poAnalysis">Buka</button></div><div class="attention-item"><i class="attention-marker blue"></i><div><strong>Distribusi belum direkonsiliasi</strong><small>Tally Fresh / Frozen → produksi</small></div><button class="row-action" data-page="bbDistributionDetail">Buka</button></div><div class="attention-item"><i class="attention-marker"></i><div><strong>Realisasi SPK / retur</strong><small>Gramasi, pack, reject, dan return BB</small></div><button class="row-action" data-page="dailyProduction">Buka</button></div></div></section></div>`}
function buildNav(){let nav=document.getElementById('workspaceNav');const searchWrap=document.createElement('div');searchWrap.className='nav-search-wrap';searchWrap.style.cssText='display:flex;align-items:center;gap:9px;width:100%;height:40px;min-width:0;flex:none;padding:0 10px;border:1px solid #2c477f;border-radius:11px;background:#102d70;box-sizing:border-box;position:relative;z-index:1;';searchWrap.innerHTML='<svg class="nav-search-icon" viewBox="0 0 20 20" aria-hidden="true"><circle cx="8.8" cy="8.8" r="5.8"/><path d="m13.2 13.2 4 4"/></svg>';const search=document.createElement('input');search.className='nav-search';search.type='text';search.autocomplete='off';search.style.cssText='display:block;flex:1 1 auto;width:1%;min-width:0;height:100%;margin:0;padding:0;border:0;outline:0;background:transparent;color:#f3f6ff;font:500 11px/1.2 \"DM Sans\",sans-serif;box-shadow:none;';search.placeholder='Cari menu atau modul';search.setAttribute('aria-label','Cari menu atau modul');const icon=searchWrap.querySelector('.nav-search-icon');icon.style.cssText='display:block;width:16px;height:16px;flex:0 0 16px;fill:none;stroke:#a9bbdf;stroke-width:1.8;stroke-linecap:round;';const clear=document.createElement('button');clear.className='nav-search-clear';clear.style.cssText='display:none;width:22px;height:22px;flex:0 0 22px;place-items:center;padding:0;border:0;border-radius:6px;background:#ffffff14;color:#d5e0f5;font:400 17px/1 Arial,sans-serif;';clear.type='button';clear.setAttribute('aria-label','Hapus pencarian');clear.textContent='×';searchWrap.append(search,clear);nav.append(searchWrap);const emptySearch=document.createElement('div');emptySearch.className='nav-search-empty';emptySearch.setAttribute('role','status');emptySearch.textContent='Menu tidak ditemukan';emptySearch.hidden=true;nav.append(emptySearch);let dash=document.createElement('button');dash.className='nav-item';dash.dataset.page='dashboard';dash.innerHTML='<span class="nav-icon">◫</span><span>Dashboard</span>';nav.append(dash);NAV.filter(x=>!x.single).forEach((group,index)=>{let d=document.createElement('details');d.className='nav-group';d.dataset.group=group.group;d.open=group.group==='PO & Pesanan';let s=document.createElement('summary');s.innerHTML=`<span class="nav-icon">${group.icon}</span><span>${esc(group.group)}</span><span class="group-caret">⌄</span>`;d.append(s);let child=document.createElement('div');child.className='nav-children';group.items.forEach(([label,page])=>{let b=document.createElement('button');b.className='nav-item';b.dataset.page=page;b.dataset.label=label;b.innerHTML=`<span class="nav-bullet"></span><span>${esc(label)}</span>`;child.append(b)});d.append(child);nav.append(d)});search.addEventListener('input',()=>{let q=search.value.trim().toLowerCase();let visible=0;searchWrap.classList.toggle('has-value',!!q);clear.style.display=q?'grid':'none';nav.querySelectorAll('.nav-group').forEach(g=>{let groupMatch=g.dataset.group.toLowerCase().includes(q);let items=[...g.querySelectorAll('.nav-item')];let matches=items.some(b=>b.dataset.label.toLowerCase().includes(q));g.hidden=!!q&&!groupMatch&&!matches;if(q&&(matches||groupMatch))g.open=true;if(!q)g.open=g.dataset.group==='PO & Pesanan';if(!g.hidden)visible++});let dashboardMatch='dashboard'.includes(q);dash.hidden=!!q&&!dashboardMatch;if(!dash.hidden)visible++;emptySearch.hidden=!q||visible>0});searchWrap.addEventListener('focusin',()=>{searchWrap.style.borderColor='#9bb4e7';searchWrap.style.boxShadow='0 0 0 3px #7096d126'});searchWrap.addEventListener('focusout',()=>{searchWrap.style.borderColor='#2c477f';searchWrap.style.boxShadow='none'});clear.addEventListener('click',()=>{search.value='';search.dispatchEvent(new Event('input'));search.focus()});nav.addEventListener('click',e=>{let b=e.target.closest('[data-page]');if(b){let key=b.dataset.page;let group=b.closest('.nav-group');if(group)group.open=true;renderPage(key);document.querySelectorAll('#workspaceNav .nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===key));if(innerWidth<720){document.getElementById('sidebar').classList.remove('open');document.getElementById('scrim').classList.remove('show')}}})}
function notify(text){toast.textContent=`${text}: hanya contoh UI, tidak ada data yang disimpan.`;toast.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>toast.classList.remove('show'),2600)}
function openDemoDrawer(mode='Detail',title='Data'){let fields=(P[window.currentPage]?.fields||[]).slice(0,8);if(window.currentPage==='users'){if(/Role/i.test(mode))fields=[['Role','select:Admin,Manager,Produksi,Gudang,QC,Finance,Purchase']];else if(/Password/i.test(mode))fields=[['Password Baru','password'],['Konfirmasi Password Baru','password']];else if(/Edit/i.test(mode))fields=[['Nama Lengkap','text'],['Email','email'],['Username','text'],['Role','select:Admin,Manager,Produksi,Gudang,QC,Finance,Purchase'],['Status','select:Aktif,Nonaktif']];else fields=[]}let isDelete=/hapus/i.test(mode);drawer.classList.add('open');backdrop.classList.add('open');drawer.innerHTML=`<div class="drawer-head"><div><span class="eyebrow">${esc(mode)} · mode prototype</span><h3>${esc(title)}</h3></div><button class="icon-button" data-close aria-label="Tutup">×</button></div><div class="drawer-body"><div class="notice-note"><b>${isDelete?'Konfirmasi visual saja.':'Pratinjau form.'}</b> Field dan aksi hanya untuk memvisualisasikan UI. Tidak ada perubahan ke website atau database.</div><div class="drawer-fields">${fields.map(fieldHTML).join('')||'<p class="card-desc">Detail mengikuti modul yang dipilih. Tidak ada data akun atau transaksi aktual yang ditampilkan.</p>'}</div><div class="form-actions"><button class="button primary" data-action="${isDelete?'Hapus demo':'Simpan demo'}">${isDelete?'Konfirmasi (demo)':'Simpan (demo)'}</button><button class="button" data-close>Batal</button></div></div>`;drawer.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeDrawer));drawer.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>notify('Mode demonstrasi')))}
function closeDrawer(){drawer.classList.remove('open');backdrop.classList.remove('open')}
function bindPageEvents(){content.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>renderPage(b.dataset.page)));content.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{let action=b.dataset.action;if(/Tambah|Buat|Edit|Detail|Pilih|Simpan|Hapus|Return|Reject|Reset Password|Simpan Role/i.test(action)){openDemoDrawer(action,action)}else notify(action)}));content.querySelectorAll('[data-row-action]').forEach(b=>b.addEventListener('click',()=>openDemoDrawer(b.dataset.rowAction,document.querySelector('.page-title')?.textContent||'Detail')));content.querySelectorAll('.table-search').forEach(input=>input.addEventListener('input',()=>{let q=input.value.toLowerCase();content.querySelectorAll('.data-table tbody tr').forEach(row=>row.hidden=!row.innerText.toLowerCase().includes(q))}));content.querySelectorAll('.field input[type=file]').forEach(i=>i.disabled=true);}
function userManagementTable(){const roles=['Admin','Manager','Produksi','Gudang','QC','Finance','Purchase'];return `<section class="card table-card"><div class="card-header"><div><h2 class="card-title">Daftar Pengguna Terdaftar & Manajemen Otoritas</h2><p class="card-desc">Ubah role per pengguna, edit akun, atau hapus melalui aksi yang sesuai. Mode demo tidak menyimpan perubahan.</p></div><span class="status info">7 role teramati</span></div><div class="table-wrap"><table class="data-table"><thead><tr>${P.users.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${P.users.rows.map(row=>`<tr><td>${esc(row[0])}</td><td><span class="cell-main">${esc(row[1])}</span></td><td>${esc(row[2])}</td><td>${esc(row[3])}</td><td><div class="role-edit"><select class="select"><option>${esc(row[4])}</option>${roles.filter(x=>x!==row[4]).map(x=>`<option>${x}</option>`).join('')}</select><button class="row-action" data-action="Simpan Role">Simpan</button></div></td><td><span class="status ${row[5]==='Aktif'?'':'muted'}">${esc(row[5])}</span></td><td><button class="row-action" data-row-action="Edit Akun">Edit</button><button class="row-action" data-page="userPassword">Reset password</button><button class="row-action danger-action" data-row-action="Hapus User">Hapus</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>Data pengguna disamarkan untuk prototype.</span><div class="pagination"><button>‹</button><button class="current">1</button><button>2</button><button>›</button></div></div></section>`}
function renderPage(key){window.currentPage=key;if(location.hash!=='#'+key)history.replaceState(null,'','#'+key);const p=P[key]||P.dashboard;document.title=`${p.title} — Alfar ERP`;document.getElementById('crumbTitle').textContent=p.title;document.querySelectorAll('#workspaceNav .nav-item').forEach(el=>el.classList.toggle('active',el.dataset.page===key));if(key==='dashboard'){content.innerHTML=renderDashboard(p);bindPageEvents();return}let html=pageHeader(p);if(p.unavailable)html+=`<div class="notice-note warning-note"><b>Belum terverifikasi di website:</b> ${esc(p.desc)} Prototype mempertahankan menu ini sebagai item navigasi, dengan fungsi dan field diberi tanda rancangan.</div>`;if(p.note)html+=`<div class="notice-note"><b>Catatan audit:</b> ${esc(p.note)}</div>`;if(p.filters?.length)html+=`<section class="card filter-card"><div class="filter-heading"><div><h2 class="card-title">Filter & pencarian</h2><p class="card-desc">Gunakan filter untuk membatasi daftar tanpa berpindah halaman.</p></div><button class="button" data-action="Reset filter">Reset filter</button></div><div class="field-grid">${p.filters.map(fieldHTML).join('')}</div></section>`;if(p.fields?.length)html+=`<section class="card form-card"><div class="card-header"><div><h2 class="card-title">${p.formTitle||'Form / detail proses'}</h2><p class="card-desc">Field mengikuti fungsi halaman; tindakan di prototype tidak menyimpan data.</p></div><span class="status info">Mode demonstrasi</span></div><div class="field-grid">${p.fields.map(fieldHTML).join('')}</div><div class="form-actions">${(p.actions||[]).filter(a=>/^(Simpan|Daftarkan|Eksekusi|Perbarui)/i.test(a)).slice(0,1).map((a,i)=>`<button class="button ${i===0?'primary':''}" data-action="${esc(a)}">${esc(a)}</button>`).join('')}</div></section>`;if(p.columns)html+=key==='users'?userManagementTable():tableHTML(p);else if(!p.fields?.length)html+=`<section class="card empty-state"><span class="empty-icon">▤</span><strong>Detail modul</strong><p>Pilih tindakan atau filter untuk menelusuri halaman ini.</p></section>`;if(p.actions?.length){let primary=p.actions.find(a=>/Tambah|Buat|Daftarkan|Jadwalkan/.test(a));let formAction=p.actions.find(a=>/^(Simpan|Daftarkan|Eksekusi|Perbarui)/i.test(a));let extras=p.actions.filter(a=>a!==primary&&a!==formAction);if(extras.length)html+=`<section class="action-strip card"><span class="card-desc">Aksi tambahan</span><div>${extras.map(a=>`<button class="button" data-action="${esc(a)}">${esc(a)}</button>`).join('')}</div></section>`}html+=`<div class="illustration-note footer-note">ⓘ Prototype UI/UX · tidak terhubung ke database atau API</div>`;content.innerHTML=html;bindPageEvents()}
function init(){buildNav();document.getElementById('menuToggle').addEventListener('click',()=>{document.getElementById('sidebar').classList.toggle('open');document.getElementById('scrim').classList.toggle('show')});document.getElementById('scrim').addEventListener('click',()=>{document.getElementById('sidebar').classList.remove('open');document.getElementById('scrim').classList.remove('show')});backdrop.addEventListener('click',closeDrawer);document.querySelectorAll('.sidebar-bottom [data-page]').forEach(b=>b.addEventListener('click',()=>renderPage(b.dataset.page)));document.querySelectorAll('.sidebar-bottom [data-action]').forEach(b=>b.addEventListener('click',()=>notify(b.dataset.action)));document.getElementById('themeToggle').addEventListener('click',()=>{document.body.classList.toggle('theme-dark');showThemeToast()});document.getElementById('chatLauncher').addEventListener('click',()=>document.getElementById('chatPanel').classList.toggle('open'));document.getElementById('chatClose').addEventListener('click',()=>document.getElementById('chatPanel').classList.remove('open'));document.getElementById('chatSend').addEventListener('click',()=>notify('Chat hanya tampilan demo, pesan tidak dikirim'));window.addEventListener('hashchange',()=>{let k=location.hash.slice(1);if(P[k])renderPage(k)});let initial=location.hash.slice(1);renderPage(P[initial]?initial:'dashboard')}
function showThemeToast(){notify(document.body.classList.contains('theme-dark')?'Tema gelap':'Tema terang')}
init();
